import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyThongBao = () => {
    const [tabActive, setTabActive] = useState('view'); // 'view' hoặc 'send'
    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');

    // Giả lập danh sách thông báo đã có
    const [notifications, setNotifications] = useState([
        {
            id: 1,
            title: "Bảo trì thang máy",
            body: "Thang máy block A sẽ được bảo trì vào lúc 9h sáng mai.",
            date: "22/04/2026",
            sender: "AD"
        }
    ]);

    const handleSendNotification = () => {
        if (!title.trim() || !content.trim()) return;

        const newNoti = {
            id: Date.now(),
            title: title,
            body: content,
            date: new Date().toLocaleDateString('vi-VN'),
            sender: "AD"
        };

        setNotifications([newNoti, ...notifications]); // Thêm mới lên đầu
        setTitle('');
        setContent('');
        setTabActive('view'); // Gửi xong tự động chuyển về trang xem
    };

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            {/* Thanh Tab điều hướng */}
            <div style={{ padding: '20px', display: 'flex', gap: '15px' }}>
                <button 
                    onClick={() => setTabActive('view')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'view' ? '#333' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'view' ? '#fff' : '#333', cursor: 'pointer', transition: '0.3s'
                    }}
                >
                    Khung thông báo
                </button>
                <button 
                    onClick={() => setTabActive('send')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'send' ? '#8b5e5e' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'send' ? '#fff' : '#333', cursor: 'pointer', transition: '0.3s'
                    }}
                >
                    Gửi thông báo
                </button>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', overflow: 'hidden' }}>

                {tabActive === 'view' ? (
                    /* --- KHUNG THÔNG BÁO (CHỈ XEM) --- */
                    <div style={{ 
                        height: '100%', overflowY: 'auto', display: 'flex', 
                        flexDirection: 'column', gap: '15px', paddingRight: '10px' 
                    }}>
                        {notifications.length > 0 ? notifications.map(noti => (
                            <div key={noti.id} style={{
                                backgroundColor: 'rgba(255,255,255,0.9)', padding: '20px', 
                                borderRadius: '20px', boxShadow: '0 4px 6px rgba(0,0,0,0.1)'
                            }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                                    <span style={{ fontWeight: 'bold', color: '#8b5e5e', fontSize: '16px' }}>{noti.title}</span>
                                    <span style={{ fontSize: '12px', color: '#666' }}>{noti.date}</span>
                                </div>
                                <p style={{ margin: 0, fontSize: '14px', color: '#333', lineHeight: '1.5' }}>{noti.body}</p>
                                <div style={{ marginTop: '10px', fontSize: '11px', color: '#999', textAlign: 'right' }}>
                                    Người gửi: <strong>{noti.sender}</strong>
                                </div>
                            </div>
                        )) : (
                            <div style={{ textAlign: 'center', color: '#fff', marginTop: '50px', opacity: 0.8 }}>
                                Chưa có thông báo nào được đăng.
                            </div>
                        )}
                    </div>
                ) : (
                    /* --- GỬI THÔNG BÁO --- */
                    <div style={{ 
                        backgroundColor: 'rgba(255,255,255,0.15)', backdropFilter: 'blur(10px)',
                        borderRadius: '25px', padding: '30px', display: 'flex', 
                        flexDirection: 'column', gap: '20px', border: '1px solid rgba(255,255,255,0.2)'
                    }}>
                        <h3 style={{ color: '#fff', margin: '0 0 10px 0' }}>Soạn thông báo mới</h3>

                        <div>
                            <label style={{ color: '#fff', display: 'block', marginBottom: '8px', fontSize: '14px' }}>Tiêu đề</label>
                            <input 
                                style={{ width: '100%', padding: '12px 15px', borderRadius: '12px', border: 'none', outline: 'none', boxSizing: 'border-box' }}
                                placeholder="Vd: Thông báo tiền điện tháng 4..."
                                value={title}
                                onChange={(e) => setTitle(e.target.value)}
                            />
                        </div>

                        <div>
                            <label style={{ color: '#fff', display: 'block', marginBottom: '8px', fontSize: '14px' }}>Nội dung chi tiết</label>
                            <textarea 
                                style={{ 
                                    width: '100%', height: '150px', padding: '15px', borderRadius: '12px', 
                                    border: 'none', outline: 'none', boxSizing: 'border-box', resize: 'none',
                                    fontFamily: 'inherit'
                                }}
                                placeholder="Nhập nội dung thông báo tại đây..."
                                value={content}
                                onChange={(e) => setContent(e.target.value)}
                            />
                        </div>

                        <button 
                            onClick={handleSendNotification}
                            disabled={!title.trim() || !content.trim()}
                            style={{ 
                                alignSelf: 'flex-end', padding: '12px 40px', borderRadius: '12px', 
                                border: 'none', backgroundColor: '#8b5e5e', color: '#fff', 
                                fontWeight: 'bold', cursor: 'pointer', transition: '0.3s',
                                opacity: (title.trim() && content.trim()) ? 1 : 0.5
                            }}
                        >
                            Gửi ngay
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default QuanLyThongBao;
